// Generated by scripts/build_gjh_startup_pack.py. Each consumer still checks
// the original asset's SHA-256 and structural constraints after unpacking.
const NAMES = __STARTUP_ASSET_NAMES__;
const known = new Set(NAMES);
const packURL = new URL('./startup-assets.pack', import.meta.url);
const MAX_BYTES = 10 * 1024 * 1024;
let shared = null, controller = null, released = false;

async function loadPack() {
  controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 4000);
  try {
    const response = await fetch(packURL, {signal: controller.signal});
    if (!response.ok) throw Error('pack unavailable');
    const length = Number(response.headers.get('content-length'));
    if (Number.isFinite(length) && length > MAX_BYTES) throw Error('pack too large');
    const bytes = await response.arrayBuffer();
    if (bytes.byteLength < 12 || bytes.byteLength > MAX_BYTES) throw Error('invalid pack size');
    const view = new DataView(bytes);
    if (new TextDecoder().decode(new Uint8Array(bytes, 0, 8)) !== 'GJHPACK1') throw Error('invalid pack');
    const headerLength = view.getUint32(8, true), start = 12 + headerLength;
    if (headerLength > 65536 || start > bytes.byteLength) throw Error('invalid pack header');
    const entries = JSON.parse(new TextDecoder().decode(new Uint8Array(bytes, 12, headerLength)));
    if (!entries || Array.isArray(entries) || Object.keys(entries).length !== NAMES.length) throw Error('invalid pack entries');
    let end = 0;
    for (const name of NAMES) {
      const entry = entries[name];
      if (!Array.isArray(entry) || entry.length !== 2 || !Number.isSafeInteger(entry[0]) ||
          !Number.isSafeInteger(entry[1]) || entry[0] !== end || entry[1] <= 0) throw Error('invalid pack entry');
      end += entry[1];
      if (start + end > bytes.byteLength) throw Error('truncated pack');
    }
    if (start + end !== bytes.byteLength) throw Error('invalid pack length');
    return {bytes, entries, start};
  } catch {
    // A missing, damaged or slow pack must not make the mall unavailable.
    // Individual requests retain the pre-existing validators and fallbacks.
    return null;
  } finally {
    clearTimeout(timer);
    controller = null;
  }
}

function waitForPack(promise, signal) {
  if (!signal) return promise;
  if (signal.aborted) return Promise.reject(new DOMException('Aborted', 'AbortError'));
  return new Promise((resolve, reject) => {
    const abort = () => reject(new DOMException('Aborted', 'AbortError'));
    signal.addEventListener('abort', abort, {once: true});
    promise.then(value => { signal.removeEventListener('abort', abort); resolve(value); }, error => {
      signal.removeEventListener('abort', abort); reject(error);
    });
  });
}

export async function fetchStartupAsset(url, options = {}) {
  const target = new URL(url, import.meta.url), name = target.pathname.split('/').pop();
  const expected = new URL(name, import.meta.url);
  if (released || !known.has(name) || target.href !== expected.href) return fetch(target, options);
  const pack = await waitForPack(shared ||= loadPack(), options.signal);
  if (!pack) return fetch(target, options);
  const [offset, length] = pack.entries[name];
  return new Response(pack.bytes.slice(pack.start + offset, pack.start + offset + length), {status: 200});
}

// Startup models are parsed into their own Three.js resources. Releasing the
// shared bytes avoids keeping the whole transfer alive for the rest of a visit.
export function releaseStartupAssetPack() {
  released = true;
  controller?.abort();
  shared = null;
}
